const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad3=n=>String(n).padStart(3,'0');
const vkOf=(s,a)=>s+':'+a;
const parseVk=vk=>{const [s,a]=String(vk).split(':').map(Number);return {s,a}};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const dayKey=(d=new Date())=>{const z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};
const daysBetween=(a,b)=>Math.round((new Date(b)-new Date(a))/86400000);
const stripTags=s=>String(s||'').replace(/<sup[^>]*>.*?<\/sup>/gi,'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();
const uzFix=s=>String(s||'').replace(/([oOgG])[`'‘’]/g,(m,l)=>l+'ʻ').replace(/([A-Za-zʻ])[`'’](?=[A-Za-z])/g,'$1ʼ');
const surahName=s=>NAMES[s-1]||('Sura '+s);
function juzOf(s,a){let j=1;for(let i=0;i<JUZ.length;i++){const p=parseVk(JUZ[i]);if(s>p.s||(s===p.s&&a>=p.a))j=i+1}return j}
function uzNum(n){return n===Infinity||n===0?'∞':String(n)}

