function mistake(vk,src,word){const m=S.mem[vk];if(m){m.m=(m.m||0)+1;m.s=Math.max(0,(m.s||1)-1)}
  S.mistakes.unshift({vk,src,word:word||'',t:Date.now()});if(S.mistakes.length>400)S.mistakes.length=400;save()}
function mistakeCounts(){const c={};for(const x of S.mistakes)c[x.vk]=(c[x.vk]||0)+1;return c}
