const memCache=new Map();
async function getJSON(url,{timeout=15000,tries=2}={}){
  if(memCache.has(url))return memCache.get(url);
  let lastErr;
  for(let i=0;i<tries;i++){
    const ctl=new AbortController();const t=setTimeout(()=>ctl.abort(),timeout);
    try{const r=await fetch(url,{signal:ctl.signal,headers:{Accept:'application/json'}});clearTimeout(t);
      if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();memCache.set(url,j);return j}
    catch(e){clearTimeout(t);lastErr=e;await sleep(400*(i+1))}
  }
  throw lastErr;
}
function lsCache(key,ttlDays,fn){return async()=>{
  try{const c=JSON.parse(localStorage.getItem('qc.'+key)||'null');if(c&&Date.now()-c.t<ttlDays*864e5)return c.v}catch(e){}
  const v=await fn();try{localStorage.setItem('qc.'+key,JSON.stringify({t:Date.now(),v}))}catch(e){}return v}}

