async function pickTranslation(){
  if(S.settings.transId)return S.settings.transId;
  try{const list=await loadTranslations();const uz=list.filter(t=>t.lang.includes('uzbek'));
    const latin=uz.find(t=>/latin/i.test(t.name))||uz.find(t=>/sodi[qk]/i.test(t.name+' '+t.author))||uz[0];
    if(latin){S.settings.transId=latin.id;save();return latin.id}}catch(e){}
  return null;
}

/* verses of a surah, normalized */
const surahCache=new Map();
async function loadSurah(s){
  if(surahCache.has(s))return surahCache.get(s);
  const p=(async()=>{
    let verses;
    try{verses=await loadSurahQuranCom(s)}
    catch(e){verses=await loadSurahAlq(s)}
    try{await attachTajweed(s,verses)}catch(e){}
    return verses;
  })();
  surahCache.set(s,p);
  p.catch(()=>surahCache.delete(s));
  return p;
}
async function loadSurahQuranCom(s){
  const tid=await pickTranslation();
  const out=[];let page=1,total=1;
  do{
    const url=`${QA}/verses/by_chapter/${s}?language=uz&words=true&word_fields=text_uthmani&fields=text_uthmani,page_number,juz_number${tid?'&translations='+tid:''}&per_page=50&page=${page}`;
    const j=await getJSON(url);
    total=(j.pagination&&j.pagination.total_pages)||1;
    for(const v of j.verses){
      const words=(v.words||[]).filter(w=>w.char_type_name==='word').map((w,i)=>({p:w.position||i+1,t:w.text_uthmani||w.text||'',au:w.audio_url||'',tr:(w.translation&&/uzbek/i.test(w.translation.language_name||'')&&w.translation.text)||'',tl:(w.transliteration&&w.transliteration.text)||''}));
      const tr=v.translations&&v.translations[0]?uzFix(stripTags(v.translations[0].text)):'';
      out.push({vk:v.verse_key,s,a:v.verse_number,page:v.page_number,juz:v.juz_number,text:v.text_uthmani||words.map(w=>w.t).join(' '),words,trans:tr});
    }
    page++;
  }while(page<=total);
  if(!out.length)throw new Error('empty');
  return out;
}
async function loadSurahAlq(s){
  const j=await getJSON(`${ALQ}/surah/${s}/editions/quran-uthmani,uz.sodik`);
  const ar=j.data[0].ayahs,tr=(j.data[1]&&j.data[1].ayahs)||[];
  return ar.map((x,i)=>{
    let t=x.text;if(s!==1&&x.numberInSurah===1){const parts=t.split(' ');if(parts.length>4&&/^\u0628\u0650\u0633\u0652\u0645\u0650/.test(parts[0]))t=parts.slice(4).join(' ')}
    const words=t.split(/\s+/).filter(Boolean).map((w,k)=>({p:k+1,t:w,au:`wbw/${pad3(s)}_${pad3(x.numberInSurah)}_${pad3(k+1)}.mp3`,tr:'',tl:''}));
    return {vk:vkOf(s,x.numberInSurah),s,a:x.numberInSurah,page:x.page,juz:x.juz,text:t,words,trans:tr[i]?uzFix(tr[i].text):''};
  });
}
async function attachTajweed(s,verses){
  const j=await getJSON(`${QA}/quran/verses/uthmani_tajweed?chapter_number=${s}`);
  const map=new Map((j.verses||[]).map(v=>[v.verse_key,v.text_uthmani_tajweed]));
  for(const v of verses){const html=map.get(v.vk);if(!html)continue;
    const ws=parseTajweed(html);if(ws.length===v.words.length)ws.forEach((runs,i)=>v.words[i].runs=runs)}
}
function parseTajweed(html){
  const doc=new DOMParser().parseFromString('<div>'+html+'</div>','text/html');
  const chars=[];
  (function walk(node,cls){for(const n of node.childNodes){
    if(n.nodeType===3){for(const ch of n.nodeValue)chars.push([ch,cls])}
    else if(n.nodeType===1){if(n.classList.contains('end'))continue;const c=n.tagName.toLowerCase()==='tajweed'?(n.getAttribute('class')||cls):cls;walk(n,c)}
  }})(doc.body.firstChild,null);
  const words=[];let cur=[];
  for(const [ch,cls] of chars){
    if(/\s/.test(ch)){if(cur.length){words.push(cur);cur=[]}continue}
    const last=cur[cur.length-1];if(last&&last.c===cls)last.t+=ch;else cur.push({t:ch,c:cls});
  }
  if(cur.length)words.push(cur);
  return words.filter(w=>w.some(r=>/[\u0621-\u064A\u0671-\u06D3]/.test(r.t)));
}

/* recitation timing (word segments) for chapter reciters */
const timingCache=new Map();
async function loadTimings(rid,s){
  const key=rid+'/'+s;if(timingCache.has(key))return timingCache.get(key);
  const p=(async()=>{
    let url,ts;
    try{const j=await getJSON(`${QA}/chapter_recitations/${rid}/${s}?segments=true`);
      const af=j.audio_file||(j.audio_files&&j.audio_files[0]);url=af.audio_url;ts=af.timestamps||af.verse_timings}
    catch(e){const j=await getJSON(`${QDC}/audio/reciters/${rid}/audio_files?chapter=${s}&segments=true`);
      const af=j.audio_files[0];url=af.audio_url;ts=af.verse_timings||af.timestamps}
    const map=new Map();
    for(const t of ts||[]){
      const from=t.timestamp_from,to=t.timestamp_to;
      const segs=(t.segments||[]).filter(x=>Array.isArray(x)&&x.length>=3).map(x=>{
        let p,st,en;if(x.length>=4){p=x[0]+1;st=x[2];en=x[3]}else{p=x[0];st=x[1];en=x[2]}
        if(st<from-1000){st+=from;en+=from}return {p,st,en}});
      map.set(t.verse_key,{from,to,segs});
    }
    if(!url)throw new Error('no audio');
    return {url,map};
  })();
  timingCache.set(key,p);p.catch(()=>timingCache.delete(key));return p;
}
async function search(q){
  const j=await getJSON(`${QA}/search?q=${encodeURIComponent(q)}&size=20&language=uz`);
  const r=(j.search&&j.search.results)||[];
  return r.map(x=>({vk:x.verse_key,text:stripTags(x.text),tr:x.translations&&x.translations[0]?uzFix(stripTags(x.translations[0].text)):''}));
}
async function loadTafsir(id,vk){
  const j=await getJSON(`${QA}/tafsirs/${id}/by_ayah/${vk}`);
  return (j.tafsir&&j.tafsir.text)||'';
}
function sanitizeHTML(html){
  const doc=new DOMParser().parseFromString('<div>'+html+'</div>','text/html');
  const ok=new Set(['P','BR','B','I','STRONG','EM','H2','H3','H4','UL','OL','LI','SPAN','DIV','BLOCKQUOTE']);
  (function clean(n){for(const c of Array.from(n.children)){
    if(!ok.has(c.tagName)){c.replaceWith(...Array.from(c.childNodes));continue}
    for(const a of Array.from(c.attributes))c.removeAttribute(a.name);clean(c)}})(doc.body.firstChild);
  return doc.body.firstChild.innerHTML;
}

/* ---------- Arabic helpers ---------- */
function normAr(s){return String(s||'').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g,'').replace(/[\u0671\u0623\u0625\u0622]/g,'\u0627').replace(/\u0649/g,'\u064A').replace(/\u0629/g,'\u0647').replace(/\u0624/g,'\u0648').replace(/\u0626/g,'\u064A').replace(/[^\u0621-\u064A]/g,'')}
function alignWords(expected,spoken){
  const E=expected.map(normAr),Sp=spoken.map(normAr).filter(Boolean);
  const n=E.length,m=Sp.length,dp=Array.from({length:n+1},()=>new Uint16Array(m+1));
  const eq=(a,b)=>a===b||(a.length>3&&b.length>3&&(a.includes(b)||b.includes(a)));
  for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=eq(E[i],Sp[j])?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);
  const res=new Array(n).fill('miss');let i=0,j=0;
  while(i<n&&j<m){if(eq(E[i],Sp[j])){res[i]='ok';i++;j++}else if(dp[i+1][j]>=dp[i][j+1]){i++}else{j++}}
  /* words skipped while extra spoken words exist nearby are marked as wrong */
  let extra=m-res.filter(x=>x==='ok').length;
  for(let k=0;k<n&&extra>0;k++)if(res[k]==='miss'){res[k]='bad';extra--}
  const score=n?Math.round(res.filter(x=>x==='ok').length/n*100):0;
  return {res,score};
}
const TJ_HINT={
  idgham_ghunnah:'Idgʻom gʻunna bilan: nun sokin yoki tanvin keyingi harfga singib, burun orqali oʻqiladi.',
  idgham_wo_ghunnah:'Idgʻom gʻunnasiz: nun sokin yoki tanvin keyingi harfga (lom yoki ro) toʻliq singadi.',
  iqlab:'Iqlob: nun sokin yoki tanvin “mim” tovushiga aylanadi.',
  ikhafa:'Ixfo: nun sokin yoki tanvin yashirin holda, burun orqali yengil oʻqiladi.',
  idgham_shafawi:'Idgʻomi shafaviy: mim keyingi mimga singib ketadi.',
  ikhafa_shafawi:'Ixfoi shafaviy: mim “bo” harfi oldidan yashirin oʻqiladi.',
  idgham_mutajanisayn:'Idgʻomi mutajonisayn: maxraji bir xil ikki harf qoʻshib oʻqiladi.',
  idgham_mutaqaribayn:'Idgʻomi mutaqoribayn: maxraji yaqin ikki harf qoʻshib oʻqiladi.',
  ham_wasl:'Vasl: keyingi soʻzdagi hamzatul-vasl oʻqilmaydi, ikki soʻz bir-biriga ulanadi.',
  laam_shamsiyah:'Lom shamsiya: “al”dagi lom oʻqilmaydi, keyingi harf tashdid bilan oʻqiladi.'
};
function joinHints(w,next){
  const out=new Set();
  if(w&&w.runs){const tail=w.runs.slice(-2);for(const r of tail)if(r.c&&/idgham|iqlab|ikhafa/.test(r.c))out.add(r.c)}
  if(next){
    if(next.runs){let k=0;for(const r of next.runs){k+=r.t.length;if(r.c==='ham_wasl'||r.c==='laam_shamsiyah')out.add(r.c);if(k>=3)break}}
    else if(/^\u0671/.test(next.t))out.add('ham_wasl');
  }
  return Array.from(out).map(c=>TJ_HINT[c]).filter(Boolean);
}

