    if(p.body==='moon'){ctx.save();ctx.fillStyle='rgba(232,242,255,.95)';ctx.shadowColor='rgba(200,225,255,.6)';ctx.shadowBlur=30;ctx.beginPath();ctx.arc(cx,cy,26,0,6.28);ctx.fill();
      ctx.shadowBlur=0;ctx.globalCompositeOperation='destination-out';ctx.beginPath();ctx.arc(cx+11,cy-6,23,0,6.28);ctx.fill();ctx.restore()}
    else{ctx.save();const sg=ctx.createRadialGradient(cx,cy,0,cx,cy,46);sg.addColorStop(0,'rgba(245,250,255,1)');sg.addColorStop(.5,'rgba(195,222,255,.7)');sg.addColorStop(1,'rgba(150,190,255,0)');ctx.fillStyle=sg;ctx.beginPath();ctx.arc(cx,cy,46,0,6.28);ctx.fill();ctx.restore()}
