let uzVoice=null,voiceChecked=false;
function findVoice(){if(voiceChecked)return uzVoice;const vs=speechSynthesis.getVoices();if(!vs.length)return null;voiceChecked=true;
  uzVoice=vs.find(v=>/^uz/i.test(v.lang))||null;return uzVoice}
async function speakMeaning(st,tok){
  if(!('speechSynthesis' in window))return;
  const v=findVoice();if(!v){if(!speakMeaning.warned){speakMeaning.warned=true;toast('Brauzeringizda oʻzbekcha ovoz topilmadi, maʼno ovozli oʻqilmaydi')}return}
  const vs=await loadSurah(st.s).catch(()=>null);const x=vs&&vs.find(q=>q.a===st.a);if(!x||!x.trans)return;
  await new Promise(res=>{const u=new SpeechSynthesisUtterance(x.trans);u.voice=v;u.lang=v.lang;u.rate=.95;u.onend=res;u.onerror=res;speechSynthesis.speak(u);
    const iv=setInterval(()=>{if(tok!==P.token){speechSynthesis.cancel();clearInterval(iv);res()}},200)});
}

/* ---------- chime ---------- */
let actx;
function chime(){
  try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();const t=actx.currentTime;
    [523.25,659.25,783.99,1046.5].forEach((f,i)=>{const o=actx.createOscillator(),g=actx.createGain();o.type='sine';o.frequency.value=f;
      g.gain.setValueAtTime(0,t+i*.12);g.gain.linearRampToValueAtTime(.16,t+i*.12+.02);g.gain.exponentialRampToValueAtTime(.0001,t+i*.12+1.6);
      o.connect(g).connect(actx.destination);o.start(t+i*.12);o.stop(t+i*.12+1.7)})}catch(e){}
}

/* ---------- offline download ---------- */
async function downloadSurah(s){
  if(!('caches' in window)){toast('Brauzeringiz oflayn saqlashni qoʻllamaydi');return}
  const rid=S.settings.reciter;const c=await caches.open(AUDIO_CACHE);
  try{await loadSurah(s)}catch(e){toast('Matnni yuklab boʻlmadi');return}
  const urls=new Set();
  if(!wholeOnly(rid,s))for(let a=1;a<=COUNTS[s-1];a++){try{urls.add((await clipFor(rid,s,a)).src)}catch(e){}if(isFile(rid)&&urls.size)break}
  if(wholeOnly(rid,s)){try{urls.add((await clipFor(rid,s,-1)).src)}catch(e){}}
  if(s!==1&&!isSync(rid)&&!isWhole(rid))try{urls.add((await clipFor(rid,1,1)).src)}catch(e){}
  let n=0,fail=0;const list=[...urls];
  for(const u of list){
    try{let r;try{r=await fetch(u,{mode:'cors'})}catch(e){r=await fetch(u,{mode:'no-cors'})}
      if(r.ok||r.type==='opaque')await c.put(u,r);else fail++}catch(e){fail++}
    n++;if(n%5===0||n===list.length)toast(`Yuklab olinmoqda: ${n}/${list.length}`,1500);
  }
  toast(fail?`Yuklab olindi, lekin ${fail} ta fayl xato berdi`:`${surahName(s)} surasi oflayn tinglash uchun saqlandi`);
}

