function wordHTML(w){
  const inner=S.settings.tajweed&&w.runs?w.runs.map(r=>r.c?`<span class="tj-${esc(r.c)}">${esc(r.t)}</span>`:esc(r.t)).join(''):esc(w.t);
  return `<span class="w" data-p="${w.p}" tabindex="0">${inner}</span>`;
}
function verseHTML(v){
  const vk=v.vk,id=`v-${v.s}-${v.a}`,bm=S.bookmarks[vk],mem=S.mem[vk],note=S.notes[vk];
  return `<article class="verse ${mem?'memorized':''}" id="${id}" data-vk="${vk}">
    <div class="vtop"><span class="vk">${vk}</span><span class="mem-dot" title="Yodlangan"></span>
      <span class="small muted">${v.page?v.page+'-sahifa · ':''}${v.juz||juzOf(v.s,v.a)}-juz</span>
      <div class="vact">
        <button class="icon-btn" data-act="play" title="Shu oyatdan tinglash" aria-label="Shu oyatdan tinglash"><svg><use href="#ic-play"/></svg></button>
        <button class="icon-btn" data-act="repeat" title="Shu oyatni takrorlash" aria-label="Shu oyatni takrorlash"><svg><use href="#ic-repeat"/></svg></button>
        <button class="icon-btn ${mem?'on':''}" data-act="mem" title="Yodladim deb belgilash" aria-label="Yodladim deb belgilash"><svg><use href="#ic-check"/></svg></button>
        <button class="icon-btn ${bm?'on':''}" data-act="bm" title="Xatchoʻp" aria-label="Xatchoʻp"><svg><use href="#ic-bookmark"/></svg></button>
        <button class="icon-btn ${note?'on':''}" data-act="note" title="Izoh yozish" aria-label="Izoh yozish"><svg><use href="#ic-note"/></svg></button>
        <button class="icon-btn" data-act="tafsir" title="Tafsir" aria-label="Tafsir"><svg><use href="#ic-tafsir"/></svg></button>
        <button class="icon-btn" data-act="mic" title="Ovozimni yozish va tekshirish" aria-label="Ovozimni yozish va tekshirish"><svg><use href="#ic-mic"/></svg></button>
        <button class="icon-btn" data-act="more" title="Yana: ulashish, oʻxshash oyatlar" aria-label="Yana: ulashish, oʻxshash oyatlar"><svg><use href="#ic-more"/></svg></button>
      </div></div>
    <div class="atext ${UI.hidden?'hidden-text':''} ${UI.hint?'hint':''}" lang="ar" dir="rtl">${v.words.map(wordHTML).join(' ')}\u00A0<span class="ayah-end${v.a>99?' n3':''}"><b>${arNum(v.a)}</b></span></div>
    ${S.settings.translit&&v.words.some(w=>w.tl)?`<div class="translit">${esc(v.words.map(w=>w.tl).join(' '))}</div>`:''}
    ${S.settings.showTrans&&v.trans?`<div class="trans">${esc(v.trans)}</div>`:''}
    ${note?`<div class="extra small" style="color:var(--gold2)">📝 ${esc(note)}</div>`:''}
    <div class="extra" data-extra></div>
  </article>`;
}
function renderVerses(){
  const box=$('#reader');if(!box||!UI.verses)return;
  const vs=UI.verses;let h='';const ch=CHAPTERS[UI.s-1];
  const banner=`<div class="sura-banner" aria-label="${esc(ch.name)} surasi"><span class="sb-side">\u062A\u0631\u062A\u064A\u0628\u0647\u0627<br>${arNum(UI.s)}</span><span class="sb-name">\u0633\u0648\u0631\u0629 ${esc(ch.ar||ch.name)}</span><span class="sb-side">\u0622\u064A\u0627\u062A\u0647\u0627<br>${arNum(ch.count)}</span></div>`;
  const basm=UI.s!==1&&UI.s!==9?`<div class="basmala">\u0628\u0650\u0633\u0652\u0645\u0650 \u0671\u0644\u0644\u064E\u0651\u0647\u0650 \u0671\u0644\u0631\u064E\u0651\u062D\u0652\u0645\u064E\u0640\u0670\u0646\u0650 \u0671\u0644\u0631\u064E\u0651\u062D\u0650\u064A\u0645\u0650</div>`:'';
  if(S.settings.view==='madina'){renderMadina(box,vs);document.documentElement.style.setProperty('--ar-size',S.settings.fontSize+'px');return}
  if(S.settings.view==='mushaf'){let lastPage=null;
    for(const v of vs){if(v.page&&v.page!==lastPage){h+=`<span class="page-sep">${v.page}-sahifa</span>`;lastPage=v.page}h+=verseHTML(v)}
    box.className='mushaf';box.innerHTML=banner+basm+`<div class="verses">${h}</div>`;
  }else{box.className='';box.innerHTML=banner+basm+`<div class="verses">${vs.map(verseHTML).join('')}</div>`}
  document.documentElement.style.setProperty('--ar-size',S.settings.fontSize+'px');
}
function bindToolbar(s){
  $('#recSel').onchange=e=>{S.settings.reciter=e.target.value;save();toast('Qori: '+reciterLabel(e.target.value));
    if(P.playing&&P.cfg){startProgram(Object.assign({},P.cfg,{reciter:e.target.value,from:P.cfg.reading&&P.step?P.step.a:P.cfg.from}))}};
  $('#tbRepeat').onclick=()=>openRepeat({s,from:S.last.s===s?S.last.a:1,to:COUNTS[s-1]});
  $('#tbHide').onclick=e=>{UI.hidden=!UI.hidden;e.currentTarget.classList.toggle('on',UI.hidden);$$('#reader .atext,#reader .mp-lines').forEach(x=>x.classList.toggle('hidden-text',UI.hidden));toast(UI.hidden?'Yodlash rejimi: soʻzni bosib moʻralashingiz mumkin':'Matn koʻrsatildi')};
  $('#tbHint').onclick=e=>{UI.hint=!UI.hint;e.currentTarget.classList.toggle('on',UI.hint);if(UI.hint&&!UI.hidden)$('#tbHide').click();$$('#reader .atext').forEach(x=>x.classList.toggle('hint',UI.hint))};
  $('#tbTaj').onclick=()=>{S.settings.tajweed=!S.settings.tajweed;save();viewRead(s,0)};
  $('#tbTr').onclick=e=>{S.settings.showTrans=!S.settings.showTrans;save();e.currentTarget.classList.toggle('on',S.settings.showTrans);renderVerses()};
  $('#tbFull').onclick=()=>openFocus(s);
  $('#tbPaper').onclick=e=>{S.settings.paper=!S.settings.paper;save();applyPaper();e.currentTarget.classList.toggle('on',S.settings.paper)};
  $('#tbView').onclick=()=>{S.settings.view=S.settings.view==='mushaf'?'ayah':'mushaf';save();viewRead(s,0)};
  $('#tbMadina').onclick=()=>{S.settings.view=S.settings.view==='madina'?'ayah':'madina';save();viewRead(s,0)};
  $('#tbFm').onclick=()=>{S.settings.fontSize=clamp(S.settings.fontSize-2,22,64);save();document.documentElement.style.setProperty('--ar-size',S.settings.fontSize+'px')};
  $('#tbFp').onclick=()=>{S.settings.fontSize=clamp(S.settings.fontSize+2,22,64);save();document.documentElement.style.setProperty('--ar-size',S.settings.fontSize+'px')};
  $('#tbDl').onclick=()=>downloadSurah(s);
  $('#ayahSel').onchange=e=>{const a=+e.target.value;if(!a)return;const el=document.getElementById(`v-${s}-${a}`);el&&el.scrollIntoView({behavior:'smooth',block:'center'});S.last.a=a;save()};
}

/* ---------- global click delegation ---------- */
document.addEventListener('click',e=>{
  const go_=e.target.closest('[data-go]');if(go_){e.preventDefault();go(go_.dataset.go);return}
  const op=e.target.closest('[data-open]');if(op){const [s,a]=op.dataset.open.split('/');go(`read/${s}${a?'/'+a:''}`);return}
  const ls=e.target.closest('[data-listen]');if(ls){const [s,a]=ls.dataset.listen.split('/').map(Number);if(UI.route!=='read'||UI.s!==s)go(`read/${s}/${a||1}`);startReading(s,a||1);return}
  if(e.target.closest('[data-close]')){closeSheet();return}
  const w=e.target.closest('#reader .w');if(w){onWordClick(w,e);return}
  const act=e.target.closest('[data-act]');if(act){const v=act.closest('.verse');if(v)verseAction(act.dataset.act,v.dataset.vk,v,act);return}
  if(!e.target.closest('#pop'))closePop();
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){closePop();closeSheet()}
  if(e.target.matches('input,textarea,select'))return;
  if(e.key===' '&&P.cfg){e.preventDefault();togglePause()}
  if(e.key==='Enter'&&e.target.classList&&e.target.classList.contains('w'))onWordClick(e.target,e);
});

function verseAction(act,vk,el,btn){
  const {s,a}=parseVk(vk);
  if(act==='play'){S.last={s,a};save();startReading(s,a)}
  else if(act==='repeat')openRepeat({s,from:a,to:a});
  else if(act==='mem'){const on=!S.mem[vk];markMem(vk,on);el.classList.toggle('memorized',on);btn.classList.toggle('on',on);if(on){logActivity(1);toast('Barakalloh! Oyat yodlanganlar roʻyxatiga qoʻshildi')}}
  else if(act==='bm')openBookmark(vk,btn);
  else if(act==='note')openNote(vk);
  else if(act==='tafsir')openTafsir(vk);
  else if(act==='mic')toggleMicPanel(vk,el);
  else if(act==='more')openVerseMore(vk);
}

/* ---------- word popover ---------- */
function verseData(vk){return UI.verses&&UI.verses.find(v=>v.vk===vk)}
function onWordClick(wEl,e){
  const vEl=wEl.closest('.verse');const vk=vEl.dataset.vk;const v=verseData(vk);if(!v)return;const p=+wEl.dataset.p;
  if(UI.hidden){wEl.classList.add('peek');setTimeout(()=>wEl.classList.remove('peek'),2600)}
  if(UI.anchor&&UI.anchor.vk===vk&&UI.anchor.p!==p){
    const p1=Math.min(UI.anchor.p,p),p2=Math.max(UI.anchor.p,p);UI.anchor=null;
    $$('.w.sel').forEach(x=>x.classList.remove('sel'));
    for(let i=p1;i<=p2;i++)vEl.querySelector(`.w[data-p="${i}"]`)?.classList.add('sel');
    showPhrasePop(v,p1,p2,wEl);return;
  }
  UI.anchor=null;$$('.w.sel').forEach(x=>x.classList.remove('sel'));
  showWordPop(v,p,wEl);
}
function placePop(anchor){
  const pop=$('#pop');pop.hidden=false;const r=anchor.getBoundingClientRect();const pw=pop.offsetWidth,ph=pop.offsetHeight;
  let x=r.left+r.width/2-pw/2,y=r.bottom+10;if(y+ph>innerHeight-10)y=Math.max(10,r.top-ph-10);
  pop.style.left=clamp(x,10,innerWidth-pw-10)+'px';pop.style.top=y+'px';
}
function repsSeg(){return `<div class="row" style="justify-content:center;margin-top:8px"><span class="small muted">Takror:</span><div class="seg" id="popReps">${[1,3,5,10].map(n=>`<button data-r="${n}" class="${UI.popReps===n?'on':''}">${n}×</button>`).join('')}</div></div>`}
function bindReps(){const sg=$('#popReps');sg&&(sg.onclick=e=>{const b=e.target.closest('[data-r]');if(!b)return;UI.popReps=+b.dataset.r;$$('#popReps button').forEach(x=>x.classList.toggle('on',x===b))})}
function showWordPop(v,p,wEl){
  const w=v.words.find(x=>x.p===p),next=v.words.find(x=>x.p===p+1);
  const hints=joinHints(w,next);
  const pop=$('#pop');
  pop.innerHTML=`<div class="pw">${esc(w.t)}</div>
    ${w.tr||w.tl?`<div class="pm">${w.tl?`<i>${esc(w.tl)}</i>`:''}${w.tr&&w.tl?' — ':''}${esc(w.tr)}</div>`:''}
    ${next&&hints.length?`<div class="hint"><b>Keyingi soʻz bilan qoʻshib oʻqiladi.</b><br>${hints.map(esc).join('<br>')}</div>`:''}
    ${repsSeg()}
    <div class="acts">
      <button class="btn" id="pwIso"><svg><use href="#ic-speaker"/></svg>Alohida talaffuz</button>
      <button class="btn" id="pwQ"><svg><use href="#ic-play"/></svg>Qori ovozida (tilovat ichida)</button>
      ${next?`<button class="btn primary" id="pwJ"><svg><use href="#ic-play"/></svg>Keyingi soʻz bilan qoʻshib</button>`:''}
      <button class="btn ghost" id="pwSel">Birikmani tanlash…</button>
    </div>`;
  placePop(wEl);bindReps();
  $('#pwIso').onclick=()=>playWordIsolated(v.s,v.a,[w],UI.popReps);
  $('#pwQ').onclick=()=>playSpan(v.s,v.a,p,p,UI.popReps);
  next&&($('#pwJ').onclick=()=>playSpan(v.s,v.a,p,p+1,UI.popReps));
  $('#pwSel').onclick=()=>{UI.anchor={vk:v.vk,p};wEl.classList.add('sel');closePop(true);toast('Endi birikmaning oxirgi soʻzini bosing')};
}
function showPhrasePop(v,p1,p2,wEl){
  const ws=v.words.filter(x=>x.p>=p1&&x.p<=p2);const hints=new Set();
  for(let i=0;i<ws.length-1;i++)joinHints(ws[i],ws[i+1]).forEach(h=>hints.add(h));
  const pop=$('#pop');
  pop.innerHTML=`<div class="pw" style="font-size:30px">${esc(ws.map(x=>x.t).join(' '))}</div>
    <div class="pm">${ws.length} soʻzli birikma</div>
    ${hints.size?`<div class="hint">${[...hints].map(esc).join('<br>')}</div>`:''}
    ${repsSeg()}
    <div class="acts">
      <button class="btn primary" id="phQ"><svg><use href="#ic-play"/></svg>Qori ovozida qoʻshib</button>
      <button class="btn" id="phIso"><svg><use href="#ic-speaker"/></svg>Har soʻzni alohida</button>
    </div>`;
  placePop(wEl);bindReps();
  $('#phQ').onclick=()=>playSpan(v.s,v.a,p1,p2,UI.popReps);
  $('#phIso').onclick=()=>playWordIsolated(v.s,v.a,ws,UI.popReps);
  playSpan(v.s,v.a,p1,p2,1);
}
function closePop(keepSel){const p=$('#pop');if(!p.hidden){p.hidden=true;stopWord()}if(!keepSel){$$('.w.sel').forEach(x=>x.classList.remove('sel'))}}

/* ---------- mic panel: record + AI check ---------- */
function toggleMicPanel(vk,el){
  const box=el.querySelector('[data-extra]');if(box.innerHTML){box.innerHTML='';return}
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  box.innerHTML=`<div class="rec-box">
    <button class="btn sm" data-r="rec"><svg><use href="#ic-mic"/></svg><span>Yozishni boshlash</span></button>
    <button class="btn sm" data-r="me" disabled>Ovozimni tinglash</button>
    <button class="btn sm" data-r="qori">Qorini tinglash</button>
    <button class="btn sm" data-r="cmp" disabled>Ketma-ket solishtirish</button>
    ${SR?`<button class="btn sm primary" data-r="ai">Yoddan tekshirish (beta)</button>`:`<span class="small muted">Yoddan tekshirish uchun Chrome yoki Edge brauzeridan foydalaning.</span>`}
    <div class="small muted" data-r="msg" style="width:100%"></div></div>`;
  const msg=box.querySelector('[data-r=msg]');const {s,a}=parseVk(vk);
  const playMine=()=>new Promise(res=>{const u=UI.rec[vk];if(!u)return res();const x=new Audio(u);x.onended=res;x.onerror=res;x.play().catch(res)});
  const playQori=()=>startProgram({s,from:a,to:a,mode:'oddiy',ayahRep:1,rangeRep:1,pause:0,hideAfter:0,reciter:S.settings.reciter});
  box.onclick=async e=>{const b=e.target.closest('[data-r]');if(!b||b.disabled)return;const k=b.dataset.r;
    if(k==='rec'){
      if(UI.mr&&UI.mr.state==='recording'){UI.mr.stop();return}
      try{const st=await navigator.mediaDevices.getUserMedia({audio:true});const mr=new MediaRecorder(st);const ch=[];UI.mr=mr;
        mr.ondataavailable=ev=>ch.push(ev.data);
        mr.onstop=()=>{st.getTracks().forEach(t=>t.stop());UI.rec[vk]&&URL.revokeObjectURL(UI.rec[vk]);UI.rec[vk]=URL.createObjectURL(new Blob(ch,{type:mr.mimeType||'audio/webm'}));
          b.querySelector('span').textContent='Qayta yozish';box.querySelector('[data-r=me]').disabled=false;box.querySelector('[data-r=cmp]').disabled=false;msg.textContent='Yozib olindi. Endi qori bilan solishtiring.'};
        mr.start();b.querySelector('span').textContent='Toʻxtatish';msg.textContent='Yozilmoqda… oyatni yoddan oʻqing.'}
      catch(err){msg.textContent='Mikrofonga ruxsat berilmadi.'}
    }
    else if(k==='me')playMine();
    else if(k==='qori')playQori();
    else if(k==='cmp'){msg.textContent='Avval sizning ovozingiz, keyin qori…';await playMine();await sleep(400);playQori()}
    else if(k==='ai')aiCheck(vk,el,msg,b);
  };
}
function aiCheck(vk,el,msg,btn){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const v=verseData(vk);if(!SR||!v)return;
  if(UI.sr){UI.sr.stop();return}
  const r=new SR();r.lang='ar-SA';r.continuous=true;r.interimResults=true;UI.sr=r;let finalT='';
  const at=el.querySelector('.atext');at.classList.add('hidden-text');
  btn.textContent='Tugatish';msg.textContent='Tinglayapman… oyatni yoddan oʻqing, soʻng “Tugatish”ni bosing.';
  r.onresult=ev=>{let interim='';for(let i=ev.resultIndex;i<ev.results.length;i++){if(ev.results[i].isFinal)finalT+=' '+ev.results[i][0].transcript;else interim+=ev.results[i][0].transcript}
    msg.textContent='Eshitildi: '+(finalT+' '+interim).trim().slice(-120)};
  r.onerror=ev=>{msg.textContent=ev.error==='not-allowed'?'Mikrofonga ruxsat berilmadi.':'Nutqni aniqlashda xato: '+ev.error};
  r.onend=()=>{UI.sr=null;btn.textContent='Yoddan tekshirish (beta)';at.classList.toggle('hidden-text',UI.hidden);
    const spoken=finalT.trim().split(/\s+/).filter(Boolean);if(!spoken.length){msg.textContent=msg.textContent.startsWith('Mikrofon')?msg.textContent:'Hech narsa eshitilmadi. Qayta urinib koʻring.';return}
    const {res,score}=alignWords(v.words.map(w=>w.t),spoken);
    at.classList.add('check-res');const ws=at.querySelectorAll('.w');ws.forEach((x,i)=>{x.classList.remove('ok','bad','miss');x.classList.add(res[i]||'miss')});
    const wrong=res.map((x,i)=>x!=='ok'?v.words[i].t:null).filter(Boolean);
    if(wrong.length){mistake(vk,'ovozli tekshiruv',wrong.slice(0,3).join(' '))}else{reviewed(vk);logActivity(1)}
    msg.innerHTML=`Natija: <b>${score}%</b>. ${score>=90?'Barakalloh, juda yaxshi!':score>=60?'Yaxshi, qizil va sariq soʻzlarni yana takrorlang.':'Bu oyatni yana tinglab, takrorlang.'} <span class="muted">(Yashil — toʻgʻri, sariq — tushib qolgan, qizil — xato. Sunʼiy intellekt harakatlarni farqlamaydi, natija taxminiy.)</span>`;
    setTimeout(()=>at.classList.remove('check-res'),15000);
  };
  try{r.start()}catch(e){UI.sr=null;msg.textContent='Nutqni aniqlashni boshlab boʻlmadi.'}
}

/* ---------- sheets ---------- */
function openSheet(title,html,onMount){$('#sheetTitle').textContent=title;$('#sheetBody').innerHTML=html;$('#sheet').hidden=false;onMount&&onMount($('#sheetBody'))}
function closeSheet(){$('#sheet').hidden=true;$('#sheetBody').innerHTML=''}
const MODE_HELP={oddiy:'Har bir oyat belgilangan marta takrorlanadi, soʻng butun oraliq qaytadan boshlanadi.',
  ikki:'Avval har bir oyat alohida koʻp marta, soʻng butun oraliq uzluksiz bir necha marta oʻqiladi.',
  bogla:'Ustozlar usuli: 1-oyat, 2-oyat, 1–2, 3-oyat, 1–3… Oyatlar bir-biriga ulanib, yodda mustahkam qoladi.'};
function openRepeat({s,from,to}){
  const R=Object.assign({},S.lastRepeat);const n=COUNTS[s-1];
  const pages=UI.verses&&UI.s===s?UI.verses:null;
  openSheet(`Takrorlash · ${surahName(s)}`,`
   <div class="stack">
    <div class="grid g2">
      <div class="field"><span class="lbl">Qaysi oyatdan</span><input type="number" id="rFrom" min="1" max="${n}" value="${from}"></div>
      <div class="field"><span class="lbl">Qaysi oyatgacha</span><input type="number" id="rTo" min="1" max="${n}" value="${to}"></div>
    </div>
    <div class="row"><button class="chip" data-q="one">Shu oyat</button><button class="chip" data-q="all">Butun sura</button>${pages?'<button class="chip" data-q="page">Shu sahifa</button>':''}<button class="chip" data-q="next5">Keyingi 5 oyat</button></div>
    <div class="field"><span class="lbl">Usul</span><div class="seg" id="rMode">
      <button data-m="oddiy">Oddiy</button><button data-m="ikki">Ikki bosqichli</button><button data-m="bogla">Bogʻlab yodlash</button></div>
      <span class="small muted" id="rHelp"></span></div>
    <div class="grid g3">
      <div class="field"><span class="lbl">Har bir oyat necha marta</span><input type="number" id="rA" min="0" max="999" value="${R.ayahRep}"><span class="small muted">0 — cheksiz</span></div>
      <div class="field"><span class="lbl">Butun oraliq necha marta</span><input type="number" id="rR" min="0" max="999" value="${R.rangeRep}"><span class="small muted">0 — cheksiz</span></div>
      <div class="field" id="rLinkF"><span class="lbl">Bogʻlash takrori</span><input type="number" id="rL" min="1" max="50" value="${R.linkRep}"></div>
    </div>
    <div class="field"><span class="lbl">Oyatlar orasidagi pauza (oʻzingiz qaytarib aytishingiz uchun)</span>
      <div class="seg" id="rPause">${[[0,'Yoʻq'],[1,'1 s'],[2,'2 s'],[3,'3 s'],[5,'5 s'],[-1,'Oyat uzunligicha']].map(([v,l])=>`<button data-v="${v}">${l}</button>`).join('')}</div></div>
    <div class="field"><span class="lbl">Necha marta tinglagach matn avtomatik yashirilsin</span><input type="number" id="rH" min="0" max="99" value="${R.hideAfter}"><span class="small muted">0 — yashirilmaydi</span></div>
    <div class="field"><span class="lbl">Qori</span><select id="rRec">${reciterOptions(S.settings.reciter)}</select></div>
    <div class="switch"><span>Tugaganda ovozli signal</span><input type="checkbox" id="rChime" ${S.settings.chime?'checked':''}></div>
    <div class="card small" id="rSum" style="padding:12px"></div>
    <button class="btn primary" id="rGo" style="justify-content:center"><svg><use href="#ic-play"/></svg>Takrorlashni boshlash</button>
   </div>`,b=>{
    const setMode=m=>{R.mode=m;$$('#rMode button',b).forEach(x=>x.classList.toggle('on',x.dataset.m===m));$('#rHelp',b).textContent=MODE_HELP[m];$('#rLinkF',b).style.display=m==='bogla'?'':'none';sum()};
    const setPause=v=>{R.pause=v;$$('#rPause button',b).forEach(x=>x.classList.toggle('on',+x.dataset.v===v));sum()};
    const cfg=()=>({s,from:clamp(+$('#rFrom',b).value||1,1,n),to:clamp(+$('#rTo',b).value||1,1,n),mode:R.mode,ayahRep:Math.max(0,+$('#rA',b).value||0),rangeRep:Math.max(0,+$('#rR',b).value||0),linkRep:Math.max(1,+$('#rL',b).value||1),pause:R.pause,hideAfter:Math.max(0,+$('#rH',b).value||0),reciter:$('#rRec',b).value});
    const sum=()=>{const c=cfg();if(c.to<c.from){$('#rSum',b).textContent='“Gacha” raqami “dan” raqamidan kichik boʻlmasligi kerak.';return}
      const t=countSteps(c);$('#rSum',b).innerHTML=`${fmtRange(c)} · <b>${t===Infinity?'cheksiz':t+' marta'}</b> oyat ijro etiladi${c.hideAfter?`, ${c.hideAfter} marta tinglangan oyat yashiriladi`:''}.`};
    setMode(R.mode);setPause(R.pause);
    b.oninput=sum;
    $('#rMode',b).onclick=e=>{const x=e.target.closest('[data-m]');x&&setMode(x.dataset.m)};
    $('#rPause',b).onclick=e=>{const x=e.target.closest('[data-v]');x&&setPause(+x.dataset.v)};
    b.querySelectorAll('[data-q]').forEach(q=>q.onclick=()=>{const k=q.dataset.q;let f=from,t=to;
      if(k==='one'){t=f}else if(k==='all'){f=1;t=n}else if(k==='next5'){f=from;t=Math.min(n,from+4)}
      else if(k==='page'){const pg=(pages.find(v=>v.a===from)||{}).page;const same=pages.filter(v=>v.page===pg);f=same[0].a;t=same[same.length-1].a}
      $('#rFrom',b).value=f;$('#rTo',b).value=t;sum()});
    $('#rGo',b).onclick=()=>{const c=cfg();if(c.to<c.from)return;S.settings.chime=$('#rChime',b).checked;S.settings.reciter=c.reciter;
      S.lastRepeat={mode:c.mode,ayahRep:c.ayahRep,rangeRep:c.rangeRep,linkRep:c.linkRep,pause:c.pause,hideAfter:c.hideAfter};save();closeSheet();
      if(UI.route!=='kitob'&&(UI.route!=='read'||UI.s!==s))go(`read/${s}/${c.from}`);
      $$('#reader .atext,#reader .mp-lines').forEach(x=>x.classList.toggle('hidden-text',UI.hidden));
      startProgram(c)};
  });
}
const BM_COLORS={yashil:'#6fd39a',moviy:'#6fb3ff',sariq:'#f2c46b',qizil:'#ff8f8f',binafsha:'#b9a6ff'};
function openBookmark(vk,btn){
  const cur=S.bookmarks[vk];
  openSheet(`Xatchoʻp · ${vk}`,`<div class="stack"><p class="muted small">Rangli guruh tanlang: masalan, yashil — yodlanganlar, sariq — takrorlash kerak.</p>
    <div class="row">${Object.entries(BM_COLORS).map(([k,c])=>`<button class="chip ${cur&&cur.g===k?'on':''}" data-g="${k}" style="border-color:${c}"><span style="color:${c}">●</span> ${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div>
    ${cur?'<button class="btn" id="bmDel">Xatchoʻpni oʻchirish</button>':''}</div>`,b=>{
    b.querySelectorAll('[data-g]').forEach(x=>x.onclick=()=>{S.bookmarks[vk]={g:x.dataset.g,t:Date.now()};save();btn&&btn.classList.add('on');closeSheet();toast('Xatchoʻp saqlandi')});
    const d=$('#bmDel',b);d&&(d.onclick=()=>{delete S.bookmarks[vk];save();btn&&btn.classList.remove('on');closeSheet();toast('Xatchoʻp oʻchirildi')});
  });
}
function openNote(vk){
  openSheet(`Izoh · ${vk}`,`<div class="stack"><textarea id="nt" rows="5" placeholder="Masalan: ustoz aytgan tajvid qoidasi, maʼnosi haqida fikr…">${esc(S.notes[vk]||'')}</textarea>
    <div class="row"><button class="btn primary" id="ntSave">Saqlash</button>${S.notes[vk]?'<button class="btn" id="ntDel">Oʻchirish</button>':''}</div></div>`,b=>{
    $('#ntSave',b).onclick=()=>{const t=$('#nt',b).value.trim();if(t)S.notes[vk]=t;else delete S.notes[vk];save();closeSheet();if(UI.route==='read')renderVerses();toast('Izoh saqlandi')};
    const d=$('#ntDel',b);d&&(d.onclick=()=>{delete S.notes[vk];save();closeSheet();if(UI.route==='read')renderVerses()});
  });
}
async function openTafsir(vk){
  openSheet(`Tafsir · ${surahName(parseVk(vk).s)} ${parseVk(vk).a}`,loaderHTML('Tafsir yuklanmoqda…'));
  let list=[];try{list=await loadTafsirs()}catch(e){}
  const pref=['uzbek','russian','english','arabic'];
  list.sort((a,b)=>{const ia=pref.indexOf(a.lang),ib=pref.indexOf(b.lang);return (ia<0?9:ia)-(ib<0?9:ib)});
  let id=S.settings.tafsirId||(list[0]&&list[0].id);
  const render=async()=>{
    const body=$('#sheetBody');if(!body)return;
    body.innerHTML=`<div class="stack">${list.length?`<select id="tfSel">${list.map(t=>`<option value="${t.id}" ${t.id==id?'selected':''}>${esc(t.name)} — ${esc(t.lang)}</option>`).join('')}</select>`:''}
      <p class="small muted">Oʻzbek tilidagi tafsir mavjud boʻlmasa, boshqa tildagisi koʻrsatiladi.</p><div id="tfBody">${loaderHTML()}</div></div>`;
    const sel=$('#tfSel');sel&&(sel.onchange=e=>{id=+e.target.value;S.settings.tafsirId=id;save();render()});
    try{const html=await loadTafsir(id,vk);$('#tfBody').innerHTML=`<div class="tafsir-text">${sanitizeHTML(html)||'<p class="muted">Bu oyat uchun tafsir matni topilmadi.</p>'}</div>`}
    catch(e){$('#tfBody').innerHTML='<div class="err">Tafsirni yuklab boʻlmadi. Internetni tekshiring.</div>'}
  };
  render();
}

/* ---------- PLAN (Sabaq · Sabqi · Manzil) ---------- */
const KIND={sabaq:'Sabaq',sabqi:'Sabqi',manzil:'Manzil'};
const INTERVALS=[1,2,4,7,14,30];
function orderList(){const o=[];if(S.plan.dir==='fotiha')for(let s=1;s<=114;s++)o.push(s);else{for(let s=114;s>=1;s--)o.push(s)}return o}
function computePlan(){
  const today=dayKey(),items=[];
  /* Sabaq: next new ayahs */
  const need=S.plan.daily,newV=[];
  outer:for(const s of orderList())for(let a=1;a<=COUNTS[s-1];a++){if(!S.mem[vkOf(s,a)]){newV.push(vkOf(s,a));if(newV.length>=need)break outer}}
  groupRanges(newV).forEach(r=>items.push({kind:'sabaq',...r,vks:newV.filter(vk=>{const p=parseVk(vk);return p.s===r.s&&p.a>=r.from&&p.a<=r.to})}));
  /* Sabqi: recently memorized */
  const recent=Object.entries(S.mem).filter(([vk,m])=>{const d=daysBetween(m.d,today);return d>=1&&d<=S.plan.sabqiDays}).map(([vk])=>vk);
  groupRanges(recent).forEach(r=>items.push({kind:'sabqi',...r}));
  /* Manzil: older memorization, due by spaced intervals */
  const old=Object.entries(S.mem).filter(([vk,m])=>daysBetween(m.d,today)>S.plan.sabqiDays)
    .map(([vk,m])=>({vk,ov:daysBetween(m.r||m.d,today)/INTERVALS[clamp(m.s||0,0,5)]})).filter(x=>x.ov>=1).sort((a,b)=>b.ov-a.ov).slice(0,S.plan.manzil).map(x=>x.vk);
  groupRanges(old).forEach(r=>items.push({kind:'manzil',...r}));
  items.forEach((it,i)=>it.id=it.kind+'-'+it.s+'-'+it.from+'-'+i);
  return {date:today,items};
}
function todayPlan(force){if(force||!S.plan.today||S.plan.today.date!==dayKey()){S.plan.today=computePlan();save()}return S.plan.today}
function viewPlan(){
  const plan=todayPlan();const done=plan.items.filter(i=>i.done).length;
  app.innerHTML=`
  <section class="hero"><div class="greet">Hifz rejasi</div><h1>Bugun nima qilamiz?</h1>
   <p class="muted">Anʼanaviy usul: <b>Sabaq</b> — yangi dars, <b>Sabqi</b> — yaqinda yodlanganlarni takrorlash, <b>Manzil</b> — eski yodlamalarni unutmaslik uchun aylanma takrorlash.</p></section>
  <div class="grid g2">
   <div class="card stack">
    <h3>Reja sozlamalari</h3>
    <div class="field"><span class="lbl">Har kuni nechta yangi oyat</span><input type="number" id="pDaily" min="1" max="50" value="${S.plan.daily}"></div>
    <div class="field"><span class="lbl">Qayerdan boshlaymiz</span><div class="seg" id="pDir"><button data-d="nas" class="${S.plan.dir==='nas'?'on':''}">Nos surasidan (oxiridan)</button><button data-d="fotiha" class="${S.plan.dir==='fotiha'?'on':''}">Fotiha surasidan</button></div></div>
    <div class="field"><span class="lbl">Sabqi: necha kunlik yodlamalar</span><input type="number" id="pSabqi" min="1" max="30" value="${S.plan.sabqiDays}"></div>
    <div class="field"><span class="lbl">Manzil: kuniga nechta eski oyat</span><input type="number" id="pManzil" min="5" max="300" value="${S.plan.manzil}"></div>
    <button class="btn" id="pRegen">Rejani yangilash</button>
   </div>
   <div class="card stack">
    <h3>Bugungi natija</h3>
    <div class="stat"><b>${done}/${plan.items.length}</b><span>bajarilgan vazifa</span></div>
    <div class="mini-bar" style="height:8px"><i style="width:${plan.items.length?done/plan.items.length*100:0}%"></i></div>
    <p class="small muted">Takrorlash paytida ilova har bir oyatni necha marta eshitganingizni hisoblaydi. Yodlangan oyatlar har takrorlangach mustahkamroq deb belgilanadi va keyingi takror vaqti uzayadi.</p>
   </div>
  </div>
  <h2 style="margin:24px 0 10px">Bugungi vazifalar</h2>
  <div class="stack" id="planList">${plan.items.length?plan.items.map(i=>`
    <div class="plan-item ${i.done?'done':''}" data-id="${i.id}">
      <div class="row spread"><div class="row"><span class="tag ${i.kind}">${KIND[i.kind]}</span><b>${fmtRange(i)}</b><span class="small muted">${i.n} oyat</span></div>
      ${i.done?'<span class="chip on">Bajarildi</span>':''}</div>
      <div class="small muted">${i.kind==='sabaq'?'Yangi dars: bogʻlab yodlash usulida tinglang, soʻng yoddan aytib koʻring.':i.kind==='sabqi'?'Yaqinda yodlanganlar: bir necha marta takrorlang.':'Eski yodlama: bir marta diqqat bilan, imkon boʻlsa yoddan oʻqing.'}</div>
      <div class="row"><button class="btn sm primary" data-pa="listen"><svg><use href="#ic-repeat"/></svg>Tinglab takrorlash</button>
      <button class="btn sm" data-pa="open">Matnni ochish</button>
      ${i.done?'':`<button class="btn sm" data-pa="done"><svg><use href="#ic-check"/></svg>${i.kind==='sabaq'?'Yodladim':'Takrorladim'}</button>`}</div>
    </div>`).join(''):`<div class="card empty">Bugun uchun vazifa yoʻq. Yangi oyat qoʻshish uchun “Rejani yangilash”ni bosing.</div>`}</div>`;
  const upd=()=>{S.plan.daily=clamp(+$('#pDaily').value||5,1,50);S.plan.sabqiDays=clamp(+$('#pSabqi').value||7,1,30);S.plan.manzil=clamp(+$('#pManzil').value||20,5,300);save()};
  ['#pDaily','#pSabqi','#pManzil'].forEach(s=>$(s).onchange=upd);
  $('#pDir').onclick=e=>{const b=e.target.closest('[data-d]');if(!b)return;S.plan.dir=b.dataset.d;save();todayPlan(true);viewPlan()};
  $('#pRegen').onclick=()=>{upd();todayPlan(true);viewPlan();toast('Reja yangilandi')};
  $('#planList').onclick=e=>{const b=e.target.closest('[data-pa]');if(!b)return;const it=plan.items.find(x=>x.id===b.closest('[data-id]').dataset.id);if(!it)return;
    if(b.dataset.pa==='open')go(`read/${it.s}/${it.from}`);
    else if(b.dataset.pa==='listen'){
      const preset=it.kind==='sabaq'?{mode:'bogla',ayahRep:5,rangeRep:3,linkRep:1,pause:-1,hideAfter:4}:it.kind==='sabqi'?{mode:'oddiy',ayahRep:2,rangeRep:2,linkRep:1,pause:0,hideAfter:0}:{mode:'oddiy',ayahRep:1,rangeRep:1,linkRep:1,pause:0,hideAfter:0};
      Object.assign(S.lastRepeat,preset);save();go(`read/${it.s}/${it.from}`);setTimeout(()=>openRepeat({s:it.s,from:it.from,to:it.to}),350)}
    else if(b.dataset.pa==='done'){
      for(let a=it.from;a<=it.to;a++){const vk=vkOf(it.s,a);if(it.kind==='sabaq')markMem(vk,true);else reviewed(vk)}
      it.done=true;logActivity(it.n);save();
      if(plan.items.every(x=>x.done))celebrate('Barakalloh! Bugungi reja toʻliq bajarildi');else toast('Belgilandi');viewPlan()}
  };
}

/* ---------- TEST (fill the blank) ---------- */
const LEVELS=[['oson','Oson',.15],['orta','Oʻrta',.3],['qiyin','Qiyin',.5],['juda','Juda qiyin',.85]];
const T={};
function viewTest(){
  const s=T.s||S.last.s||1;
  app.innerHTML=`<section class="hero"><div class="greet">Sinov</div><h1>Yodlaganingizni tekshiring</h1>
    <p class="muted">Oyatdagi tushib qolgan soʻzlarni toping. Qiyinlik oshgani sari koʻproq soʻz yashiriladi.</p></section>
   <div class="card stack" id="tSetup">
    <div class="grid g3">
      <div class="field"><span class="lbl">Sura</span><select id="tS">${CHAPTERS.map(c=>`<option value="${c.id}" ${c.id===s?'selected':''}>${c.id}. ${esc(c.name)}</option>`).join('')}</select></div>
      <div class="field"><span class="lbl">Oyatdan</span><input type="number" id="tF" min="1" value="1"></div>
      <div class="field"><span class="lbl">Oyatgacha</span><input type="number" id="tT" min="1" value="${Math.min(7,COUNTS[s-1])}"></div>
    </div>
    <div class="field"><span class="lbl">Qiyinlik</span><div class="seg" id="tL">${LEVELS.map(([k,l],i)=>`<button data-l="${i}" class="${(T.level??1)===i?'on':''}">${l}</button>`).join('')}</div></div>
    <div class="row"><button class="btn primary" id="tGo">Sinovni boshlash</button><button class="btn" id="tMem">Faqat yodlangan oyatlardan</button></div>
   </div>
   <div id="tBox" style="margin-top:14px"></div>`;
  T.level=T.level??1;
  $('#tS').onchange=e=>{T.s=+e.target.value;$('#tF').value=1;$('#tT').value=Math.min(7,COUNTS[T.s-1])};
  $('#tL').onclick=e=>{const b=e.target.closest('[data-l]');if(!b)return;T.level=+b.dataset.l;$$('#tL button').forEach(x=>x.classList.toggle('on',x===b))};
  $('#tGo').onclick=()=>{const s=+$('#tS').value;T.s=s;startTest(s,clamp(+$('#tF').value||1,1,COUNTS[s-1]),clamp(+$('#tT').value||1,1,COUNTS[s-1]))};
  $('#tMem').onclick=()=>{const keys=Object.keys(S.mem);if(!keys.length){toast('Hali yodlangan deb belgilangan oyat yoʻq');return}
    const r=groupRanges(keys);const pick=r[Math.floor(Math.random()*r.length)];T.s=pick.s;startTest(pick.s,pick.from,Math.min(pick.to,pick.from+9))};
}
async function startTest(s,from,to){
  if(to<from)[from,to]=[to,from];
  const box=$('#tBox');box.innerHTML=`<div class="card">${loaderHTML()}</div>`;
  let vs;try{vs=await loadSurah(s)}catch(e){box.innerHTML='<div class="err">Oyatlarni yuklab boʻlmadi.</div>';return}
  const pool=[...new Map(vs.flatMap(v=>v.words).map(w=>[normAr(w.t),w.t])).entries()];
  const ratio=LEVELS[T.level][2];
  const qs=vs.filter(v=>v.a>=from&&v.a<=to).map(v=>{
    const idx=v.words.map((_,i)=>i).filter(()=>Math.random()<ratio);if(!idx.length)idx.push(Math.floor(Math.random()*v.words.length));
    return {v,blanks:idx.sort((a,b)=>a-b),filled:{},wrong:{}}});
  Object.assign(T,{qs,qi:0,bi:0,ok:0,bad:0,pool,from,to,s});
  renderQ();
}
function renderQ(){
  const box=$('#tBox');const q=T.qs[T.qi];
  if(!q){const total=T.ok+T.bad,score=total?Math.round(T.ok/total*100):0;const key=`${T.s}:${T.from}-${T.to}`;
    S.testBest[key]=Math.max(S.testBest[key]||0,score);logActivity(T.qs.length);save();
    if(score>=80)celebrate('Ajoyib natija!');
    box.innerHTML=`<div class="card stack" style="text-align:center"><h2>Natija: ${score}%</h2><p class="muted">${T.ok} ta toʻgʻri, ${T.bad} ta xato · eng yaxshi natija: ${S.testBest[key]}%</p>
      <div class="row" style="justify-content:center"><button class="btn primary" id="tAgain">Yana bir bor</button><button class="btn" data-open="${T.s}/${T.from}">Oyatlarni ochish</button></div></div>`;
    $('#tAgain').onclick=()=>startTest(T.s,T.from,T.to);return}
  const bIdx=q.blanks[T.bi];const ans=q.v.words[bIdx].t;
  const html=q.v.words.map((w,i)=>{if(!q.blanks.includes(i))return esc(w.t);
    const f=q.filled[i];return `<span class="blank ${i===bIdx?'cur':''} ${f?(q.wrong[i]?'wrong':'right'):''}">${f?esc(w.t):'＿＿'}</span>`}).join(' ');
  const opts=[ans];const na=normAr(ans);
  const others=T.pool.filter(([n])=>n!==na).sort(()=>Math.random()-.5);for(const [,t] of others){if(opts.length>=4)break;opts.push(t)}
  opts.sort(()=>Math.random()-.5);
  box.innerHTML=`<div class="card stack">
    <div class="row spread"><span class="vk">${q.v.vk}</span><span class="small muted">${T.qi+1}/${T.qs.length} oyat · ✓ ${T.ok} · ✗ ${T.bad}</span></div>
    <div class="q-ar">${html} <span class="ayah-end${q.v.a>99?' n3':''}"><b>${arNum(q.v.a)}</b></span></div>
    <div class="opts">${opts.map(o=>`<button class="opt" data-o="${esc(o)}">${esc(o)}</button>`).join('')}</div>
    <div class="row"><button class="btn sm" id="tListen"><svg><use href="#ic-play"/></svg>Oyatni tinglash</button><button class="btn sm ghost" id="tSkip">Javobni koʻrsatish</button></div></div>`;
  let tries=0;
  const advance=()=>{T.bi++;if(T.bi>=q.blanks.length){T.qi++;T.bi=0}setTimeout(renderQ,550)};
  box.querySelector('.opts').onclick=e=>{const b=e.target.closest('[data-o]');if(!b)return;
    if(normAr(b.dataset.o)===na){b.classList.add('right');q.filled[bIdx]=true;if(!tries)T.ok++;advance()}
    else{b.classList.add('wrong');tries++;if(tries===1){T.bad++;q.wrong[bIdx]=true;mistake(q.v.vk,'sinov',ans)}
      if(tries>=2){q.filled[bIdx]=true;box.querySelector(`.opt[data-o="${CSS.escape(ans)}"]`)?.classList.add('right');advance()}}};
  $('#tListen').onclick=()=>playWordIsolated(q.v.s,q.v.a,[q.v.words[bIdx]],1);
  $('#tSkip').onclick=()=>{q.filled[bIdx]=true;q.wrong[bIdx]=true;T.bad++;mistake(q.v.vk,'sinov',ans);advance()};
}

/* ---------- STATS ---------- */
function viewStats(){
  const memN=Object.keys(S.mem).length,st=streak(),mc=mistakeCounts();
  const weak=Object.entries(mc).sort((a,b)=>b[1]-a[1]).slice(0,12);
  const days=[];const d=new Date();d.setDate(d.getDate()-7*16+1);
  for(let i=0;i<7*16;i++){const k=dayKey(d);const v=S.log[k]||0;days.push(`<i class="${v>40?'l3':v>15?'l2':v>0?'l1':''}" title="${k}: ${v}"></i>`);d.setDate(d.getDate()+1)}
  const juzP=JUZ.map((k,i)=>{const a=parseVk(k),b=i<29?parseVk(JUZ[i+1]):{s:115,a:1};let tot=0,m=0;
    for(let s=a.s;s<=Math.min(b.s,114);s++){const st=s===a.s?a.a:1,en=s===b.s?b.a-1:COUNTS[s-1];for(let x=st;x<=en;x++){tot++;if(S.mem[vkOf(s,x)])m++}}return {i:i+1,p:tot?m/tot:0}});
  app.innerHTML=`<section class="hero"><div class="greet">Natijalar</div><h1>Sizning yoʻlingiz</h1></section>
  <div class="grid g3">
    <div class="card stat"><b>${st}</b><span>kun uzluksiz</span></div>
    <div class="card stat"><b>${memN}</b><span>yodlangan oyat (jami ${TOTAL_AYAHS})</span></div>
    <div class="card stat"><b>${CHAPTERS.filter(c=>memCountSurah(c.id)===c.count).length}</b><span>toʻliq yodlangan sura</span></div>
  </div>
  <div class="card" style="margin-top:14px"><h3>Faollik (16 hafta)</h3><div class="heat">${days.join('')}</div></div>
  <div class="card" style="margin-top:14px"><div class="row spread"><h3>Yodlash xaritasi</h3><span class="small muted">Yashil — yodlangan qism, qizil chegara — zaif sura</span></div>
    <div class="map">${CHAPTERS.map(c=>{const m=memCountSurah(c.id),p=m/c.count;let weakS=false;
      if(m){let sum=0;for(let a=1;a<=c.count;a++){const x=S.mem[vkOf(c.id,a)];if(x)sum+=x.s||0}weakS=sum/m<1.5&&Object.keys(mc).some(vk=>parseVk(vk).s===c.id)}
      return `<button class="cell ${p>=1?'full':''} ${weakS?'weak':''}" data-open="${c.id}" title="${esc(c.name)}: ${m}/${c.count}"><i style="height:${p*100}%"></i><span>${c.id}</span></button>`}).join('')}</div></div>
  <div class="card" style="margin-top:14px"><h3>Juzlar boʻyicha</h3><div class="grid g3">${juzP.map(j=>`<div class="small"><div class="row spread"><span>${j.i}-juz</span><span class="muted">${Math.round(j.p*100)}%</span></div><div class="mini-bar"><i style="width:${j.p*100}%"></i></div></div>`).join('')}</div></div>
  <div class="grid g2" style="margin-top:14px">
    <div class="card"><h3>Zaif oyatlar</h3><div class="list">${weak.length?weak.map(([vk,n])=>`<div class="li"><span><span class="vk">${vk}</span> ${surahName(parseVk(vk).s)}</span><span class="row"><span class="small muted">${n} xato</span><button class="btn sm" data-wk="${vk}">Takrorlash</button></span></div>`).join(''):'<div class="muted small">Hozircha xato qayd etilmagan. Sinov va ovozli tekshiruvdan oʻting.</div>'}</div></div>
    <div class="card"><h3>Soʻnggi xatolar</h3><div class="list">${S.mistakes.slice(0,10).map(m=>`<div class="li small"><span><span class="vk">${m.vk}</span> ${esc(m.src)}</span><span style="font-family:var(--ar);font-size:20px">${esc(m.word)}</span></div>`).join('')||'<div class="muted small">Xatolar tarixi boʻsh.</div>'}</div></div>
  </div>
  <div class="card stack" style="margin-top:14px"><h3>Ustoz bilan ulashish</h3>
    <p class="small muted">Hisobotni nusxalab ustozingizga yuboring. Ustoz uni shu boʻlimga joylab, natijangizni koʻradi. (Maʼlumotlar faqat sizning qurilmangizda saqlanadi.)</p>
    <div class="row"><button class="btn primary" id="repMake">Hisobot yaratish</button></div><div id="repOut"></div>
    <div class="field"><span class="lbl">Shogird hisobotini ochish</span><textarea id="repIn" rows="3" placeholder="Hisobot kodini shu yerga joylang"></textarea></div>
    <div><button class="btn" id="repOpen">Koʻrish</button></div><div id="repView"></div>
  </div>`;
  app.querySelectorAll('[data-wk]').forEach(b=>b.onclick=()=>{const p=parseVk(b.dataset.wk);Object.assign(S.lastRepeat,{mode:'oddiy',ayahRep:5,rangeRep:1});go(`read/${p.s}/${p.a}`);setTimeout(()=>openRepeat({s:p.s,from:p.a,to:p.a}),350)});
  $('#repMake').onclick=()=>{
    const sur={};for(const vk of Object.keys(S.mem)){const s=parseVk(vk).s;sur[s]=(sur[s]||0)+1}
    const rep={v:1,n:S.settings.name||'Shogird',d:dayKey(),st:streak(),tm:memN,sur,weak:weak.slice(0,10)};
    const code=btoa(unescape(encodeURIComponent(JSON.stringify(rep))));
    const text=`${rep.n} — hifz hisoboti (${rep.d})\nUzluksiz faollik: ${rep.st} kun\nYodlangan oyatlar: ${rep.tm}\nSuralar: ${Object.entries(sur).map(([s,n])=>`${surahName(+s)} ${n}/${COUNTS[s-1]}`).join(', ')||'—'}\n\nHisobot kodi:\n${code}`;
    $('#repOut').innerHTML=`<code class="box">${esc(text)}</code><button class="btn sm" id="repCopy" style="margin-top:8px">Nusxalash</button>`;
    $('#repCopy').onclick=()=>navigator.clipboard.writeText(text).then(()=>toast('Nusxalandi'),()=>toast('Nusxalab boʻlmadi, matnni qoʻlda belgilang'))};
  $('#repOpen').onclick=()=>{try{let raw=$('#repIn').value.trim();const m=raw.match(/[A-Za-z0-9+/=]{20,}/g);raw=m?m[m.length-1]:raw;
    const r=JSON.parse(decodeURIComponent(escape(atob(raw))));
    $('#repView').innerHTML=`<div class="card stack" style="margin-top:10px"><h3>${esc(r.n)} · ${esc(r.d)}</h3><div class="row"><span class="chip">${r.st} kun faol</span><span class="chip">${r.tm} oyat yodlangan</span></div>
      <div class="list">${Object.entries(r.sur||{}).map(([s,n])=>`<div class="li small"><span>${surahName(+s)}</span><span>${n}/${COUNTS[s-1]}</span></div>`).join('')}</div>
      ${r.weak&&r.weak.length?`<div class="small">Zaif oyatlar: ${r.weak.map(([vk,n])=>`${vk} (${n})`).join(', ')}</div>`:''}</div>`}
    catch(e){toast('Hisobot kodi notoʻgʻri')}};
}

