  $('#sImp').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);S=deepMerge(structuredClone(DEFAULTS),d);save();applyTheme();toast('Maʼlumotlar tiklandi');viewSettings()}catch(err){toast('Fayl notoʻgʻri')}};r.readAsText(f)};
