/* the surah toolbar's download button saves everything the surah needs */
downloadSurah=function(s){return offCan()?offlineSaveSurah(s):Promise.resolve(toast('Bu manzilda oflayn saqlash ishlamaydi. Saytning asosiy (GitHub) manzilidan foydalaning.',5000))};
