/* Qurʼon — real Madina mushaf pages (KFGQPC QCF page fonts: v2 plain, v4 tajweed colour)
   and word-by-word read-along highlighting shared by every view. */
'use strict';

const QF='https://verses.quran.foundation/fonts/quran/hafs';
const MP={pages:new Map(),fonts:new Map(),io:null};

/* editions: v1 = 1405 h. print, v2 = 1421 h. print, v4 = v2 layout with tajweed colours */
function mpEd(sec){return (sec&&sec.dataset.ed)||(S.settings.tajweed?'v4':'v2')}
function mpFontName(p,ed){return 'qcf'+ed+'p'+p}
function mpLoadFont(p,ed){
  const k=mpFontName(p,ed);if(MP.fonts.has(k))return MP.fonts.get(k);
  const url=ed==='v4'?`${QF}/v4/colrv1/woff2/p${p}.woff2`:`${QF}/${ed}/woff2/p${p}.woff2`;
  const pr=new FontFace(k,`url(${url}) format('woff2')`,{display:'block'}).load().then(f=>{document.fonts.add(f);return k});
  MP.fonts.set(k,pr);pr.catch(()=>MP.fonts.delete(k));return pr;
}
/* The API pages verses by the 1405 h. print. In the 1421 h. print some lines moved to the neighbouring page,
   so a v2/v4 page is assembled from the words that really sit on it (word.page_number). */
const mpPageUrl=(p,v1)=>`${QA}/verses/by_page/${p}?words=true&word_fields=${v1?'code_v1,line_v1':'code_v2,page_number'},line_number&per_page=50`;
function mpLoadPage(p,ed){
  const v1=ed==='v1',key=(v1?'a':'b')+p;
  if(MP.pages.has(key))return MP.pages.get(key);
  const src=v1?[p]:[p-1,p,p+1].filter(x=>x>=1&&x<=604);
  const pr=Promise.all(src.map(x=>getJSON(mpPageUrl(x,v1)))).then(js=>{
    const out=[];
    for(const j of js)for(const v of (j.verses||[])){const [s,a]=v.verse_key.split(':').map(Number);
      const words=(v.words||[]).filter(w=>v1||w.page_number===p).map(w=>({p:w.position,c:v1?w.code_v1:w.code_v2,l:(v1&&w.line_v1)||w.line_number,end:w.char_type_name==='end'}));
      if(words.length)out.push({vk:v.verse_key,s,a,juz:v.juz_number,words})}
    return out});
  MP.pages.set(key,pr);pr.catch(()=>MP.pages.delete(key));return pr;
}
const BASM_AR='بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ';
function mpHeader(s){const ch=CHAPTERS[s-1]||{};
  return `<div class="ml ml-head"><div class="sura-banner mp-banner"><span class="sb-side">${arNum(s)}</span><span class="sb-name">سورة ${esc(ch.ar||ch.name||'')}</span><span class="sb-side">${arNum(ch.count||COUNTS[s-1])}</span></div></div>`}
function mpBasm(){return `<div class="ml ml-basm">${BASM_AR}</div>`}

async function mpRenderPage(sec){
  const p=+sec.dataset.page,ed=mpEd(sec);
  if(sec.dataset.done===ed)return;
  sec.dataset.done=ed;
  let vs,font;
  try{[vs,font]=await Promise.all([mpLoadPage(p,ed),mpLoadFont(p,ed)])}
  catch(e){sec.dataset.done='';sec.querySelector('.mp-lines').innerHTML='<p class="muted" style="text-align:center;font-family:var(--ui);font-size:14px">Sahifani yuklab boʻlmadi. Internetni tekshiring.</p>';return}
  const lines=new Map();let maxL=0;
  for(const v of vs)for(const w of v.words){if(!lines.has(w.l))lines.set(w.l,[]);lines.get(w.l).push({v,w});maxL=Math.max(maxL,w.l)}
  const total=p<=2?maxL:15;let h='';
  const firstVerseOn=l=>{const x=lines.get(l);return x&&x[0].v};
  for(let l=1;l<=total;l++){
    if(lines.has(l)){
      h+=`<div class="ml${p<=2?' ml-c':''}">`+lines.get(l).map(({v,w})=>`<span class="qw${w.end?' qe':''}" data-vk="${v.vk}" data-p="${w.p}">${w.c}</span>`).join('')+'</div>';
      continue;
    }
    /* empty run: surah header and/or basmala */
    let b=l;while(b+1<=total&&!lines.has(b+1))b++;
    let nl=b+1;while(nl<=15&&!lines.has(nl))nl++;
    const nv=firstVerseOn(nl);const last=vs[vs.length-1];
    const X=nv&&nv.a===1?nv.s:(last?last.s+1:0);const len=b-l+1;
    if(X>=1&&X<=114){
      if(len>=2){h+=mpHeader(X);if(X!==9&&X!==1)h+=mpBasm();else h+='<div class="ml"></div>';for(let k=2;k<len;k++)h+='<div class="ml"></div>'}
      else if(l===1&&X!==1&&X!==9&&nv&&nv.a===1)h+=mpBasm();
      else h+=mpHeader(X);
    }else for(let k=0;k<len;k++)h+='<div class="ml"></div>';
    l=b;
  }
  const box=sec.querySelector('.mp-lines');box.style.fontFamily=`'${font}'`;box.innerHTML=h;
  const f=vs[0];if(f){sec.querySelector('.mp-sura').textContent=surahName(f.s);sec.querySelector('.mp-juz').textContent=(f.juz||juzOf(f.s,f.a))+'-juz'}
  sec._vs=vs;mpFit(sec);
  if(P.playing&&P.step&&P.step.a)mpMarkVerse(vkOf(P.step.s,P.step.a));
  if(UI.hidden)box.classList.add('hidden-text');
}
/* scale each page so the longest line fills the page width */
function mpFit(sec){
  const box=sec.querySelector('.mp-lines');if(!box)return;
  box.style.setProperty('--mpfs','40px');
  let max=0;box.querySelectorAll('.ml:not(.ml-head):not(.ml-basm)').forEach(r=>{let w=0;r.querySelectorAll('.qw').forEach(q=>w+=q.getBoundingClientRect().width);max=Math.max(max,w)});
  const W=box.clientWidth;if(!W)return;
  /* pages 1–2 (Fotiha, Baqara boshi) have short centred lines: use the normal page scale */
  if(+sec.dataset.page<=2){box.style.setProperty('--mpfs',Math.min(64,W/15.6)+'px');return}
  if(max>0)box.style.setProperty('--mpfs',Math.min(64,40*W/max*0.985)+'px');
}
addEventListener('resize',()=>{clearTimeout(mpFit.t);mpFit.t=setTimeout(()=>$$('.mpage').forEach(mpFit),200)});

function renderMadina(box,vs){
  const pages=[...new Set(vs.map(v=>v.page).filter(Boolean))];
  box.className='madina';
  box.innerHTML=`<div class="mpages">${pages.map(p=>`<section class="mpage" data-page="${p}"><div class="mp-top"><span class="mp-sura"></span><span class="mp-juz"></span></div><div class="mp-lines" dir="rtl" lang="ar"><div class="mp-load">${p}-sahifa yuklanmoqda…</div></div><div class="mp-num">${arNum(p)}</div></section>`).join('')}</div>
    <div class="mw-bar" id="mwBar" hidden><b id="mwKey"></b><button class="chip" id="mwPlay">▶ Shu oyatdan</button><button class="chip" id="mwRep">↻ Takrorlash</button><button class="chip" id="mwWord">🔊 Soʻz</button><button class="icon-btn" id="mwX" aria-label="Yopish"><svg><use href="#ic-x"/></svg></button></div>`;
  if(MP.io)MP.io.disconnect();
  MP.io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)mpRenderPage(e.target)}),{rootMargin:'900px 0px'});
  $$('.mpage',box).forEach(s=>MP.io.observe(s));
  const sec=p=>`<section class="mpage" data-page="${p}"><div class="mp-top"><span class="mp-sura"></span><span class="mp-juz"></span></div><div class="mp-lines" dir="rtl" lang="ar"><div class="mp-load">${p}-sahifa yuklanmoqda…</div></div><div class="mp-num">${arNum(p)}</div></section>`;
  const sId=UI.s,edN=mpEd(null);
  for(const [p,where] of [[pages[pages.length-1]+1,'beforeend'],[pages[0]-1,'afterbegin']]){
    if(p<1||p>604)continue;
    mpLoadPage(p,edN).then(vs2=>{if(UI.s!==sId||!vs2.some(v=>v.s===sId))return;const wrap=box.querySelector('.mpages');if(!wrap||wrap.querySelector(`.mpage[data-page="${p}"]`))return;
      wrap.insertAdjacentHTML(where,sec(p));MP.io.observe(wrap.querySelector(`.mpage[data-page="${p}"]`))}).catch(()=>{});
  }
  let sel=null;
  const bar=$('#mwBar',box);
  box.onclick=e=>{
    const q=e.target.closest('.qw');if(!q)return;
    $$('.qw.sel',box).forEach(x=>x.classList.remove('sel'));
    const vk=q.dataset.vk;$$(`.qw[data-vk="${vk}"]`,box).forEach(x=>x.classList.add('sel'));
    const [s,a]=vk.split(':').map(Number);sel={s,a,p:+q.dataset.p,end:q.classList.contains('qe')};
    $('#mwKey',box).textContent=`${surahName(s)} ${a}-oyat`;bar.hidden=false;$('#mwWord',box).hidden=sel.end;
    S.last={s,a};save();
  };
  $('#mwX',box).onclick=e=>{e.stopPropagation();bar.hidden=true;$$('.qw.sel',box).forEach(x=>x.classList.remove('sel'))};
  $('#mwPlay',box).onclick=e=>{e.stopPropagation();if(sel)startReading(sel.s,sel.a)};
  $('#mwRep',box).onclick=e=>{e.stopPropagation();if(sel)openRepeat({s:sel.s,from:sel.a,to:sel.a})};
  $('#mwWord',box).onclick=async e=>{e.stopPropagation();if(!sel)return;const v=(await loadSurah(sel.s)).find(x=>x.a===sel.a);const w=v&&v.words.find(x=>x.p===sel.p);if(w)playWordIsolated(sel.s,sel.a,[w])};
  /* scroll to the remembered ayah */
  const a=S.last.s===UI.s?S.last.a:0;
  if(a>1){const v=vs.find(x=>x.a===a);const sec=v&&box.querySelector(`.mpage[data-page="${v.page}"]`);sec&&setTimeout(()=>sec.scrollIntoView({block:'start'}),80)}
}
function mpMarkVerse(vk){
  $$('.qw.vplay').forEach(x=>x.classList.remove('vplay'));
  const ws=$$(`.qw[data-vk="${vk}"]`);ws.forEach(x=>x.classList.add('vplay'));
  if(ws[0]&&Date.now()-userScrolledAt>4000){const r=ws[0].getBoundingClientRect();if(r.top<80||r.bottom>innerHeight-160)ws[0].scrollIntoView({behavior:'smooth',block:'center'})}
}

/* ---------- word-by-word read-along (all views) ---------- */
const RA={vk:'',p:0};
function raContainers(s,a){
  const out=[];const r=document.getElementById(`v-${s}-${a}`);if(r)out.push(r);
  if(typeof FX!=='undefined'&&FX.open&&FX.s===s){const f=document.getElementById('fx-'+a);if(f)out.push(f);if(FX.cur===a){const sb=$('#fxRxAr');if(sb)out.push(sb)}}
  return out;
}
function raSet(s,a,p){
  const vk=s+':'+a;if(RA.vk===vk&&RA.p===p)return;RA.vk=vk;RA.p=p;
  for(const c of raContainers(s,a))c.querySelectorAll('.w[data-p]').forEach(w=>{const q=+w.dataset.p;w.classList.toggle('hl',q===p);w.classList.toggle('rd',p>0&&q<p)});
  $$(`.qw[data-vk="${vk}"]`).forEach(w=>{if(w.classList.contains('qe'))return;const q=+w.dataset.p;w.classList.toggle('hl',q===p);w.classList.toggle('rd',p>0&&q<p)});
}
function raClear(){RA.vk='';RA.p=0;$$('.w.hl,.w.rd,.qw.hl,.qw.rd').forEach(x=>x.classList.remove('hl','rd'));$$('.qw.vplay').forEach(x=>x.classList.remove('vplay'))}
let raWarned=false;
function raNotice(rid){
  if(raWarned||!rid||hasWords(rid))return;
  raWarned=true;toast('Soʻzma-soʻz yoritish faqat ✦ belgili qorilarda aniq ishlaydi (Afasiy, Sudays, Shurayim, Husariy…). Qorini almashtirish uchun pastdagi qori ismiga bosing.',6000);
}

