'use strict';

(async function init(){
  $('#splashRose').innerHTML=rosetteSVG(3,{strokeW:1.1});
  document.documentElement.style.setProperty('--ar-size',S.settings.fontSize+'px');
  setTimeout(()=>$('#splash').classList.add('done'),8000);
  if(location.protocol==='about:'||/artifactdeploy\.com$/.test(location.hostname))document.documentElement.classList.add('ad-host');
  applyAudioPrefs();
  applyPaper();
  try{applyTheme();Sky.init()}catch(e){console.warn(e)}
  setInterval(()=>{if(S.settings.theme==='auto')applyTheme()},5*60000);

  $('#plPlay').onclick=togglePause;
  $('#plStop').onclick=()=>{stopProgram();$('#player').hidden=true;P.cfg=null};
  $('#plNext').onclick=nextAyah;$('#plPrev').onclick=prevAyah;
  $('#plSpeed').onclick=cycleSpeed;$('#plSpeed').textContent=(S.settings.speed||1)+'×';
  $('#plSleep').onclick=cycleSleep;
  $('#plQori').onclick=openReciterSheet;
  $('#plSura').onclick=openSurahSheet;
  $('#plFull').onclick=()=>openFocus();
  $('#plRelax').onclick=async()=>{await openFocus();enterRelax();openRelaxSheet()};
  bindFocus();
  $('#plRepeat').onclick=()=>{const s=P.cfg?P.cfg.s:S.last.s;const a=P.step?P.step.a:S.last.a;openRepeat({s,from:a,to:a})};
  $('#themeQuick').onclick=()=>{const order=['auto','tong','kun','kech','tun'];S.settings.theme=order[(order.indexOf(S.settings.theme)+1)%order.length];save();applyTheme();toast('Mavzu: '+THEME_LABEL[S.settings.theme])};

  await Promise.race([Promise.all([initChapters(),initReciters()]),sleep(4000)]);
  route();
  setTimeout(()=>$('#splash').classList.add('done'),400);
  if(!SYNC_RECITERS.length)initReciters();
  if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('sw.js').catch(()=>{});
  if('speechSynthesis' in window)speechSynthesis.onvoiceschanged=()=>{voiceChecked=false};
})();
